Definition nodesW (X : list Z) : list (Z * Z) := map (fun a => (a, a + 32)) X.
Definition ibW (lo hi : Z) (X : list Z) : list (Z * Z) := (lo, hi) :: nodesW X.

Lemma inside_ibW_frame : forall lo hi X a n, lo <= a -> a + n <= hi -> inside (ibW lo hi X) a n.
Proof. intros lo hi X a n H1 H2. cbn. left. lia. Qed.

Lemma inside_nodesW : forall X x a n, x ∈ X -> x <= a -> a + n <= x + 32 -> inside (nodesW X) a n.
Proof.
  intros X x a n IN H1 H2. induction X as [|y X IH]; [rewrite elem_of_nil in IN; destruct IN|].
  cbn. rewrite elem_of_cons in IN. destruct IN as [<-|IN]; [left; lia| right; exact (IH IN)].
Qed.

Lemma inside_ibW_node : forall lo hi X x a n, x ∈ X -> x <= a -> a + n <= x + 32 -> inside (ibW lo hi X) a n.
Proof. intros lo hi X x a n IN H1 H2. cbn. right. eapply inside_nodesW; eauto. Qed.

Lemma disjoint_nodesW : forall X a n, (forall x, x ∈ X -> a + n <= x \/ x + 32 <= a) -> disjoint_from (nodesW X) a n.
Proof.
  intros X a n H. induction X as [|y X IH]; [exact I|]. cbn. split.
  - apply H. rewrite elem_of_cons. left; reflexivity.
  - apply IH. intros x IN. apply H. rewrite elem_of_cons. right; exact IN.
Qed.

Lemma disjoint_ibW : forall lo hi X a n, (a + n <= lo \/ hi <= a) ->
  (forall x, x ∈ X -> a + n <= x \/ x + 32 <= a) -> disjoint_from (ibW lo hi X) a n.
Proof. intros lo hi X a n H1 H2. cbn. split; [exact H1| apply disjoint_nodesW; exact H2]. Qed.
