Lemma munch_ibW_of_frame : forall lo hi X lo' hi' m m', munch [(lo', hi')] m m' -> lo <= lo' -> hi' <= hi -> munch (ibW lo hi X) m m'.
Proof.
  intros lo hi X lo' hi' m m' MU H1 H2. eapply munch_weaken; [| exact MU]. intros u [K _]. cbn. split; [lia| exact I].
Qed.

Lemma munch_ibW_mono : forall lo hi lo' hi' X m m', munch (ibW lo' hi' X) m m' -> lo <= lo' -> hi' <= hi -> munch (ibW lo hi X) m m'.
Proof.
  intros lo hi lo' hi' X m m' MU H1 H2. eapply munch_weaken; [| exact MU]. intros u [K R]. cbn. split; [lia| exact R].
Qed.

(* [comment removed for export] *)
Lemma munch_ibW_sub : forall lo hi X X' m m', munch (ibW lo hi X) m m' -> (forall x, x ∈ X -> x ∈ X') -> munch (ibW lo hi X') m m'.
Proof.
  intros lo hi X X' m m' MU SUB. eapply munch_weaken; [| exact MU]. intros u [K R]. cbn. split; [exact K|].
  rewrite outside_nodesW in R |- *. intros x IN. apply R. apply SUB. exact IN.
Qed.

(* [comment removed for export] *)
Lemma munch_ibW_of_node_frame : forall lo hi X x a b lo' hi' m m',
  munch [(a, b); (lo', hi')] m m' -> x ∈ X -> x <= a -> b <= x + 32 -> lo <= lo' -> hi' <= hi -> munch (ibW lo hi X) m m'.
Proof.
  intros lo hi X x a b lo' hi' m m' MU IN H1 H2 H3 H4. eapply munch_weaken; [| exact MU]. intros u [K R]. cbn.
  rewrite outside_nodesW in R. split; [| split; [lia| exact I]]. pose proof (R x IN). lia.
Qed.

