Lemma mb_load {R} (ns : NS) x off nd (K : Z -> option R) r :
  ns !! x = Some nd -> (load ns x off ≫= K) = Some r -> K (get_field off nd) = Some r.
Proof. intros L H. unfold load in H. rewrite L in H. exact H. Qed.
Lemma mb_store {R} (ns : NS) x off v nd (K : NS -> option R) r :
  ns !! x = Some nd -> (store ns x off v ≫= K) = Some r -> K (<[x := set_field off v nd]> ns) = Some r.
Proof. intros L H. unfold store in H. rewrite L in H. exact H. Qed.
Lemma m_load_last (ns : NS) x off nd r : ns !! x = Some nd -> load ns x off = Some r -> r = get_field off nd.
Proof. intros L H. unfold load in H. rewrite L in H. cbn in H. congruence. Qed.
Lemma m_store_last (ns : NS) x off v nd r : ns !! x = Some nd -> store ns x off v = Some r -> r = <[x := set_field off v nd]> ns.
Proof. intros L H. unfold store in H. rewrite L in H. cbn in H. congruence. Qed.

(* [comment removed for export] *)
Definition fld_ok (off : Z) : Prop := (off =? OFF_PARENT) || (off =? OFF_LEFT) || (off =? OFF_RIGHT) || (off =? OFF_COLOR) = true.

Lemma store_dom ns a off v ns' : store ns a off v = Some ns' -> forall b, is_Some (ns' !! b) <-> is_Some (ns !! b).
Proof.
  intros ST b. destruct (store_Some_inv _ _ _ _ _ ST) as (nd & L & ->).
  destruct (Z.eq_dec a b) as [<-|NE]; [rewrite lookup_insert_eq, L; split; intros _; eexists; reflexivity|].
  rewrite lookup_insert_ne by exact NE. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma load_store_swap {R} ns a off b off' w (K : Z -> NS -> option R) :
  (a <> b \/ off <> off') -> fld_ok off -> fld_ok off' ->
  (v ← load ns a off ; ns1 ← store ns b off' w ; K v ns1) = (ns1 ← store ns b off' w ; v ← load ns1 a off ; K v ns1).
Proof.
  intros NE O1 O2. destruct (store ns b off' w) as [ns1|] eqn:ST; cbn.
  - rewrite (load_store_other _ _ _ _ _ a off ST); [| destruct NE as [NE|NE]; [left; intros E; apply NE; symmetry; exact E| right; intros E; apply NE; symmetry; exact E]| exact O2| exact O1].
    destruct (load ns a off) as [v|]; reflexivity.
  - destruct (load ns a off) as [v|]; reflexivity.
Qed.

(* [comment removed for export] *)
Lemma store_store_swap {R} ns a off v b off' v' (K : NS -> option R) :
  (a <> b \/ off <> off') -> fld_ok off -> fld_ok off' ->
  (ns1 ← store ns a off v ; ns2 ← store ns1 b off' v' ; K ns2) = (ns1 ← store ns b off' v' ; ns2 ← store ns1 a off v ; K ns2).
Proof.
  intros NE O1 O2. pose proof (store_store_comm ns a off v b off' v' NE O1 O2) as C.
  destruct (store ns a off v) as [n1|] eqn:S1; destruct (store ns b off' v') as [n1'|] eqn:S2; cbn in *.
  - destruct (store n1 b off' v') as [n2|]; destruct (store n1' a off v) as [n2'|]; cbn in *; congruence.
  - destruct (store n1 b off' v') as [n2|]; cbn in *; congruence.
  - destruct (store n1' a off v) as [n2'|]; cbn in *; congruence.
  - reflexivity.
Qed.

(* [comment removed for export] *)
Lemma load_load_swap {R} ns a off b off' (K : Z -> Z -> option R) :
  (v ← load ns a off ; w ← load ns b off' ; K v w) = (w ← load ns b off' ; v ← load ns a off ; K v w).
Proof. destruct (load ns a off), (load ns b off'); reflexivity. Qed.

