(* [comment removed for export] *)
Definition XAcc (m : mem) (X : list Z) : Prop := forall x, x ∈ X -> x mod 8 = 0 /\ aapp x 32 /\ accessible m x 32.

(* [comment removed for export] *)
Lemma ibW_awin : forall m lo hi X, XAcc m X -> aceil <= lo -> Forall awin (ibW lo hi X).
Proof.
  intros m lo hi X XA CE. unfold ibW. apply Forall_cons; [apply awin_stack; exact CE|].
  unfold nodesW. apply Forall_forall. intros iv IN. apply in_map_iff in IN. destruct IN as (x & <- & IN).
  destruct (XA x ltac:(apply (proj2 (list_elem_of_In _ _)); exact IN)) as (_ & AP & _). eapply awin_aapp; [exact AP| lia| lia].
Qed.

Lemma XAcc_transport : forall W m m' X, XAcc m X -> munch W m m' -> Forall awin W -> XAcc m' X.
Proof.
  intros W m m' X XA MU FW x IN. destruct (XA x IN) as (AL & AP & AC). split; [exact AL|]. split; [exact AP|].
  eapply accessible_transport_awin; eauto.
Qed.

(* [comment removed for export] *)
Definition ANSR (m : mem) (ns : NS) (X : list Z) : Prop :=
  ANSCells m ns /\ ns_sep ns /\ (forall a nd, ns !! a = Some nd -> a ∈ X) /\ XAcc m X.

Lemma ANSR_Xout : forall m ns X x, ANSR m ns X -> x ∈ X -> AIMG_TOP <= x /\ x + 32 <= aceil /\ x mod 8 = 0.
Proof.
  intros m ns X x (NC & SEP & INX & XA) IN. destruct (XA x IN) as (AL & AP & _).
  pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & _). auto.
Qed.

Lemma ANSR_out : forall m ns X lo hi, ANSR m ns X -> aceil <= lo -> ns_out ns lo hi.
Proof. intros m ns X lo hi NSR0 CE a nd L. pose proof NSR0 as (NC & SEP & INX & XA). pose proof (ANSR_Xout _ _ _ a NSR0 (INX a nd L)). left. lia. Qed.

Lemma ANSR_cells : forall m ns X, ANSR m ns X -> ANSCells m ns.
Proof. intros m ns X (NC & _). exact NC. Qed.

Lemma ANSR_xacc : forall m ns X, ANSR m ns X -> XAcc m X.
Proof. intros m ns X (_ & _ & _ & XA). exact XA. Qed.

Lemma ANSR_nsacc : forall m ns X, ANSR m ns X -> ANSAcc m ns.
Proof. intros m ns X (NC & SEP & INX & XA) a nd L. exact (XA a (INX a nd L)). Qed.

Lemma ANSR_intro : forall m ns X,
  ANSCells m ns -> ns_sep ns -> (forall a, is_Some (ns !! a) -> a ∈ X) -> XAcc m X -> ANSR m ns X.
Proof.
  intros m ns X NC SEP INX XA. split; [exact NC|]. split; [exact SEP|]. split; [| exact XA].
  intros a nd L. apply INX. rewrite L. eexists; reflexivity.
Qed.

(* [comment removed for export] *)
Lemma ANSR_recells : forall m m' ns X, ANSR m ns X -> ANSCells m' ns -> XAcc m' X -> ANSR m' ns X.
Proof. intros m m' ns X (NC & SEP & INX & XA) NC' XA'. split; [exact NC'|]. split; [exact SEP|]. split; [exact INX| exact XA']. Qed.

Lemma ANSR_node : forall m ns X a nd, ANSR m ns X -> ns !! a = Some nd ->
  node_wf nd /\ a ∈ X /\ (AIMG_TOP <= a /\ a + 32 <= aceil /\ a mod 8 = 0) /\ exists pad, rw_cells bsegs m a (NodeCells nd pad).
Proof.
  intros m ns X a nd NSR0 L. pose proof NSR0 as (NC & SEP & INX & XA).
  split; [exact (ANSCells_wf _ _ _ _ NC L)|]. split; [exact (INX a nd L)|]. split; [exact (ANSR_Xout _ _ _ a NSR0 (INX a nd L))|].
  exact (ANSCells_lookup _ _ _ _ NC L).
Qed.

Lemma ANSR_sep : forall m ns X a b nda ndb, ANSR m ns X -> ns !! a = Some nda -> ns !! b = Some ndb -> a <> b ->
  a + 32 <= b \/ b + 32 <= a.
Proof. intros m ns X a b nda ndb (NC & SEP & INX & XA) La Lb NE. exact (SEP a b nda ndb La Lb NE). Qed.

(* [comment removed for export] *)
Lemma ANSR_rd : forall m ns X x k, ANSR m ns X -> x ∈ X -> (k = 0 \/ k = 8 \/ k = 16 \/ k = 24) ->
  ov_read_bytes bsegs m (Z_to_bv 64 (Z.shiftr (x + k) 3 + 2147450880)) 1 = Some [b8 0].
Proof. intros m ns X x k (_ & _ & _ & XA) IN Hk. destruct (XA x IN) as (AL & _ & AC). exact (nacc_rd m x k AC AL Hk). Qed.

Lemma ANSR_rd0 : forall m ns X x, ANSR m ns X -> x ∈ X ->
  ov_read_bytes bsegs m (Z_to_bv 64 (Z.shiftr x 3 + 2147450880)) 1 = Some [b8 0].
Proof. intros m ns X x (_ & _ & _ & XA) IN. destruct (XA x IN) as (AL & _ & AC). exact (nacc_rd0 m x AC AL). Qed.

(* [comment removed for export] *)
Lemma ANSR_transport_awin : forall W m m' ns X,
  ANSR m ns X -> munch W m m' -> wmono bsegs m m' -> Forall awin W ->
  (forall a nd, ns !! a = Some nd -> disjoint_from W a 32) -> ANSR m' ns X.
Proof.
  intros W m m' ns X (NC & SEP & INX & XA) MU WM FW DJ.
  split; [eapply ANSCells_transport; eauto|]. split; [exact SEP|]. split; [exact INX|]. eapply XAcc_transport; eauto.
Qed.

Lemma ANSR_transport_frame : forall m m' ns X lo' hi',
  ANSR m ns X -> munch [(lo', hi')] m m' -> wmono bsegs m m' -> aceil <= lo' -> ANSR m' ns X.
Proof.
  intros m m' ns X lo' hi' NSR0 MU WM H1.
  eapply ANSR_transport_awin; [exact NSR0| exact MU| exact WM| repeat apply Forall_cons; [apply awin_stack; exact H1| apply Forall_nil]|].
  intros a nd L. destruct (ANSR_node _ _ _ _ _ NSR0 L) as (_ & _ & (B1 & B2 & _) & _). cbn. split; [lia| exact I].
Qed.
