  rewrite load_store_swap in H by first [ fld_ok_tac | fld_ne_tac ];
  fold_model H
with fold_model H :=
  change (load ?ns ?a OFF_PARENT) with (get_parent ns a) in H; change (load ?ns ?a OFF_LEFT) with (get_left ns a) in H;
  change (load ?ns ?a OFF_RIGHT) with (get_right ns a) in H; change (load ?ns ?a OFF_COLOR) with (get_color ns a) in H;
  change (store ?ns ?a OFF_PARENT ?v) with (set_parent ns a v) in H; change (store ?ns ?a OFF_LEFT ?v) with (set_left ns a v) in H;
