Lemma set_left_right_zero : forall ns new nd ns',
  ns !! new = Some nd -> (set_left ns new 0 ≫= λ ns5 : NS, set_right ns5 new 0) = Some ns' ->
  ns' = <[new := set_rgt 0 (set_lft 0 nd)]> ns.
Proof.
  intros ns new nd ns' L H. unfold set_left, set_right, store in H. rewrite L in H. cbn [mbind option_bind] in H.
  rewrite lookup_insert_eq in H. cbn [mbind option_bind] in H. injection H as <-.
  cbn [set_field OFF_LEFT OFF_RIGHT OFF_PARENT OFF_COLOR Z.eqb Pos.eqb]. rewrite insert_insert_eq. reflexivity.
Qed.

